import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { 
  MessageCircle, X, Paperclip, Smile, Mic, 
  Send, Clock, Check, CheckCheck,
  User, Users, Info
} from 'lucide-react';
import { io } from 'socket.io-client';

const ChatModal = ({ currentUser, isAuthenticated, onClose }) => {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [conversation, setConversation] = useState(null);
  const [adminInfo, setAdminInfo] = useState(null);
  const [socket, setSocket] = useState(null);
  const messagesEndRef = useRef(null);
  const chatInputRef = useRef(null);

  // URL de base pour les APIs
  const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

  // Initialiser Socket.io
  useEffect(() => {
    if (isAuthenticated && currentUser) {
      const newSocket = io(process.env.REACT_APP_SOCKET_URL || 'http://localhost:5000', {
        query: { userId: currentUser.id },
        transports: ['websocket']
      });

      newSocket.on('connect', () => {
        console.log('Connecté au serveur de chat');
      });

      newSocket.on('receiveMessage', (message) => {
        handleNewMessage(message);
      });

      newSocket.on('userTyping', (data) => {
        if (data.conversationId === conversation?.id && data.userId !== currentUser.id) {
          setIsTyping(true);
          setTimeout(() => setIsTyping(false), 3000);
        }
      });

      newSocket.on('messageRead', (data) => {
        updateMessageStatus(data.messageIds, 'read');
      });

      setSocket(newSocket);

      return () => {
        newSocket.disconnect();
      };
    }
  }, [isAuthenticated, currentUser, conversation]);

  // Charger la conversation
  useEffect(() => {
    if (isAuthenticated && currentUser) {
      loadOrCreateConversation();
    }
  }, [isAuthenticated, currentUser]);

  const loadOrCreateConversation = async () => {
    try {
      setIsLoading(true);
      const token = localStorage.getItem('authToken');

      // Vérifier les conversations existantes
      const response = await axios.get(`${API_URL}/messages/conversations`, {
        headers: { 
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      let conversationData = null;

      if (response.data.success && response.data.conversations.length > 0) {
        // Prendre la première conversation ouverte
        conversationData = response.data.conversations[0];
      }

      // Si pas de conversation, créer une conversation avec un admin
      if (!conversationData) {
        // Trouver un admin disponible
        const adminsResponse = await axios.get(`${API_URL}/users/admins`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });

        let adminId = null;
        if (adminsResponse.data.success && adminsResponse.data.admins.length > 0) {
          adminId = adminsResponse.data.admins[0].id;
        } else {
          // Fallback: utiliser l'admin par défaut (ID 1)
          adminId = 1;
        }

        // Créer la conversation
        const newConvResponse = await axios.post(`${API_URL}/messages/conversations/create`, 
          { admin_id: adminId },
          { headers: { 'Authorization': `Bearer ${token}` } }
        );

        if (newConvResponse.data.success) {
          conversationData = newConvResponse.data.conversation;
        }
      }

      if (conversationData) {
        setConversation(conversationData);

        // Charger les messages
        await loadMessages(conversationData.id);

        // Récupérer les infos de l'admin
        if (conversationData.admin_id) {
          const adminResponse = await axios.get(`${API_URL}/users/${conversationData.admin_id}`, {
            headers: { 'Authorization': `Bearer ${token}` }
          });

          if (adminResponse.data.success) {
            setAdminInfo(adminResponse.data.user);
          }
        }
      }

    } catch (error) {
      console.error('Erreur lors du chargement de la conversation:', error);
      setMessages([
        { 
          id: 'default',
          content: 'Une erreur est survenue lors du chargement du chat. Veuillez réessayer.',
          created_at: new Date(),
          sender: { first_name: 'Système', last_name: '', role: 'system' },
          is_read: true
        }
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  const loadMessages = async (conversationId) => {
    try {
      const token = localStorage.getItem('authToken');
      const response = await axios.get(
        `${API_URL}/messages/conversations/${conversationId}/messages`, 
        {
          headers: { 'Authorization': `Bearer ${token}` }
        }
      );

      if (response.data.success) {
        setMessages(response.data.messages || []);
      }
    } catch (error) {
      console.error('Erreur lors du chargement des messages:', error);
    }
  };

  const handleNewMessage = (message) => {
    setMessages(prev => [...prev, message]);
    scrollToBottom();
  };

  const updateMessageStatus = (messageIds, status) => {
    setMessages(prev => prev.map(msg => 
      messageIds.includes(msg.id) 
        ? { ...msg, status }
        : msg
    ));
  };

  const handleSendMessage = async () => {
    if (!inputMessage.trim() || !conversation) return;

    const messageData = {
      content: inputMessage.trim()
    };

    try {
      const token = localStorage.getItem('authToken');

      // Envoyer via API
      const response = await axios.post(
        `${API_URL}/messages/conversations/${conversation.id}/messages`, 
        messageData,
        { headers: { 'Authorization': `Bearer ${token}` } }
      );

      if (response.data.success) {
        const newMessage = response.data.message;

        // Ajouter le message localement
        handleNewMessage({
          ...newMessage,
          sender: {
            id: currentUser.id,
            first_name: currentUser.first_name,
            last_name: currentUser.last_name
          }
        });

        // Émettre via socket si disponible
        if (socket) {
          socket.emit('sendMessage', {
            conversationId: conversation.id,
            message: newMessage
          });
        }

        // Émettre l'événement de frappe
        if (socket) {
          socket.emit('typing', {
            conversationId: conversation.id,
            userId: currentUser.id
          });
        }

        setInputMessage('');
      }

    } catch (error) {
      console.error('Erreur lors de l\'envoi du message:', error);
    }
  };

  const handleTyping = () => {
    if (socket && conversation) {
      socket.emit('typing', {
        conversationId: conversation.id,
        userId: currentUser.id
      });
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Formatage de l'heure
  const formatTime = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
  };

  if (!isAuthenticated || !currentUser) {
    return (
      <div className="fixed bottom-6 right-6 w-80 sm:w-96 bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border dark:border-neutral-800 z-50">
        <div className="p-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className="h-10 w-10 rounded-full bg-white/20 flex items-center justify-center">
                <MessageCircle className="h-5 w-5" />
              </div>
              <div>
                <h3 className="font-bold">Support Nexus</h3>
                <p className="text-xs opacity-90">Connectez-vous pour chatter</p>
              </div>
            </div>
            <button onClick={onClose} className="p-2 hover:bg-white/20 rounded-lg">
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>
        <div className="p-6 text-center">
          <MessageCircle className="h-12 w-12 text-gray-400 mx-auto mb-4" />
          <p className="text-gray-600 dark:text-gray-300 mb-4">
            Connectez-vous pour discuter avec notre équipe de support
          </p>
          <button
            onClick={() => navigate('/login')}
            className="w-full py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-xl font-medium hover:opacity-90 transition-opacity"
          >
            Se connecter
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed bottom-6 right-6 w-80 sm:w-96 bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border dark:border-neutral-800 z-50">
      {/* Header avec infos admin */}
      <div className="p-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            {adminInfo?.avatar ? (
              <img 
                src={adminInfo.avatar} 
                alt={adminInfo.first_name}
                className="h-10 w-10 rounded-full border-2 border-white/30"
              />
            ) : (
              <div className="h-10 w-10 rounded-full bg-white/20 flex items-center justify-center">
                <User className="h-5 w-5" />
              </div>
            )}
            <div>
              <h3 className="font-bold">
                {adminInfo ? `${adminInfo.first_name} ${adminInfo.last_name}` : 'Support Nexus'}
              </h3>
              <p className="text-xs opacity-90">
                {adminInfo?.role === 'admin' ? 'Conseiller • En ligne' : 'En attente de conseiller'}
              </p>
            </div>
          </div>
          <div className="flex items-center space-x-2">
            <button onClick={onClose} className="p-2 hover:bg-white/20 rounded-lg">
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>

        {/* Statut de la conversation */}
        <div className="mt-2 flex items-center justify-between text-xs">
          <span className="bg-white/20 px-2 py-1 rounded">
            Ticket: #{conversation?.id?.toString().substring(0, 8)}
          </span>
          <span className="flex items-center">
            <div className="h-2 w-2 rounded-full bg-green-400 mr-1 animate-pulse"></div>
            En ligne
          </span>
        </div>
      </div>

      {/* Zone des messages */}
      <div className="h-64 sm:h-72 p-4 overflow-y-auto">
        {isLoading ? (
          <div className="flex items-center justify-center h-full">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500"></div>
          </div>
        ) : (
          <div className="space-y-3">
            {messages.map((message) => (
              <div
                key={message.id}
                className={`flex ${message.sender_id === currentUser.id ? 'justify-end' : 'justify-start'}`}
              >
                <div className={`max-w-[85%] rounded-2xl p-3 ${
                  message.sender_id === currentUser.id
                    ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none'
                    : 'bg-gray-100 dark:bg-neutral-800 text-gray-900 dark:text-white rounded-bl-none'
                }`}>
                  {message.sender_id !== currentUser.id && (
                    <div className="flex items-center space-x-2 mb-1">
                      <span className="text-xs font-medium">
                        {message.sender?.first_name || 'Support'}
                      </span>
                    </div>
                  )}
                  <p className="text-sm">{message.content}</p>
                  <div className={`flex items-center justify-between mt-2 ${
                    message.sender_id === currentUser.id ? 'text-white/80' : 'text-gray-500'
                  }`}>
                    <span className="text-xs">{formatTime(message.created_at)}</span>
                    {message.sender_id === currentUser.id && (
                      <div className="flex items-center space-x-1">
                        {message.is_read ? (
                          <CheckCheck className="h-3 w-3 text-blue-300" />
                        ) : (
                          <Check className="h-3 w-3" />
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-gray-100 dark:bg-neutral-800 rounded-2xl rounded-bl-none p-3">
                  <div className="flex items-center space-x-2">
                    <div className="flex space-x-1">
                      <div className="h-2 w-2 bg-gray-400 rounded-full animate-bounce"></div>
                      <div className="h-2 w-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                      <div className="h-2 w-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                    </div>
                    <span className="text-xs text-gray-500">
                      {adminInfo?.first_name} écrit...
                    </span>
                  </div>
                </div>
              </div>
            )}

            <div ref={messagesEndRef} />
          </div>
        )}
      </div>

      {/* Zone de saisie */}
      <div className="p-3 border-t dark:border-neutral-800">
        <div className="flex items-center space-x-2">
          <div className="flex-1 relative">
            <input
              ref={chatInputRef}
              type="text"
              value={inputMessage}
              onChange={(e) => {
                setInputMessage(e.target.value);
                handleTyping();
              }}
              onKeyPress={handleKeyPress}
              placeholder="Écrivez votre message..."
              className="w-full pl-4 pr-12 py-3 rounded-xl border dark:border-neutral-700 bg-white dark:bg-neutral-800 focus:outline-none focus:ring-2 focus:ring-primary-500"
            />
          </div>
          <button
            onClick={handleSendMessage}
            disabled={!inputMessage.trim()}
            className="p-3 rounded-xl bg-primary-500 text-white hover:bg-primary-600 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Send className="h-5 w-5" />
          </button>
        </div>
        <div className="mt-2 text-xs text-gray-500 text-center">
          <Clock className="inline h-3 w-3 mr-1" />
          Temps de réponse moyen : 2-5 minutes
        </div>
      </div>
    </div>
  );
};

export default ChatModal;
